134	fn show_by_day(store: &CostStore, json: bool) -> Result<()> {
135	    let summaries = store.summarize_by_day()?;
136	    if json {
137	        println!("{}", serde_json::to_string_pretty(&summaries)?);
138	        return Ok(());
139	    }
140	
141	    println!("{}", "Daily Cost Trend".bold());
142	    println!("{}", "─".repeat(50));
143	
144	    if summaries.is_empty() {
145	        println!("No records found.");
146	        return Ok(());
147	    }
148	
149	    let max_cost = summaries
150	        .iter()
151	        .map(|s| s.total_cost_usd)
152	        .fold(0.0_f64, f64::max);
153	
154	    for s in &summaries {
155	        let bar_len = if max_cost > 0.0 {
156	            ((s.total_cost_usd / max_cost) * 30.0) as usize
157	        } else {
158	            0
159	        };
160	        let bar = "█".repeat(bar_len);
161	        println!(
162	            "  {} {} {}",
163	            s.key.dimmed(),
164	            bar.cyan(),
165	            format_usd(s.total_cost_usd).yellow(),
166	        );
167	    }
168	    Ok(())
