173	fn show_pr_detail(store: &CostStore, pr_ref: &str, json: bool) -> Result<()> {
174	    let records = store.query_by_pr(pr_ref)?;
175	
176	    if json {
177	        println!("{}", serde_json::to_string_pretty(&records)?);
178	        return Ok(());
179	    }
180	
181	    if records.is_empty() {
182	        println!("No cost records found for PR: {}", pr_ref);
183	        return Ok(());
184	    }
185	
186	    let total: f64 = records.iter().map(|r| r.cost_usd).sum();
187	    let total_in: u64 = records.iter().map(|r| r.input_tokens).sum();
188	    let total_out: u64 = records.iter().map(|r| r.output_tokens).sum();
189	
190	    println!("{}", format!("PR {} Cost Detail", pr_ref).bold());
191	    println!("{}", "─".repeat(60));
192	    println!("  Total cost:    {}", format_usd(total).green().bold());
193	    println!("  Input tokens:  {}", fmt_tokens(total_in));
194	    println!("  Output tokens: {}", fmt_tokens(total_out));
195	    println!("  Sessions:      {}", records.len());
196	    println!();
197	
198	    println!(
199	        "  {:>24} {:>14} {:>12} {:>12}",
200	        "TIMESTAMP".bold(),
201	        "MODEL".bold(),
202	        "COST".bold(),
203	        "DEV".bold(),
204	    );
205	    println!("  {}", "─".repeat(66));
206	
207	    for r in &records {
208	        println!(
209	            "  {:>24} {:>14} {:>12} {:>12}",
210	            truncate(&r.timestamp, 24),
211	            truncate(&r.model_id, 14),
212	            format_usd(r.cost_usd).yellow().to_string(),
213	            truncate(&r.developer_id, 12),
214	        );
215	    }
216	    Ok(())
217	}
