221	fn print_summary_table(title: &str, summaries: &[CostSummary], key_label: &str) {
222	    println!("{}", title.bold());
223	    println!("{}", "─".repeat(60));
224	
225	    if summaries.is_empty() {
226	        println!("No records found.");
227	        return;
228	    }
229	
230	    println!(
231	        "  {:30} {:>12} {:>10} {:>14}",
232	        key_label.bold(),
233	        "COST".bold(),
234	        "SESSIONS".bold(),
235	        "TOKENS (in+out)".bold(),
236	    );
237	    println!("  {}", "─".repeat(70));
238	
239	    for s in summaries {
240	        let tokens = fmt_tokens(s.input_tokens + s.output_tokens);
241	        println!(
242	            "  {:30} {:>12} {:>10} {:>14}",
243	            truncate(&s.key, 30),
244	            format_usd(s.total_cost_usd).yellow().to_string(),
245	            s.record_count,
246	            tokens,
247	        );
248	    }
249	}
