251	// ── Formatting helpers ────────────────────────────────────────────────────────
252	
253	fn format_usd(amount: f64) -> String {
254	    format!("${:.4}", amount)
255	}
256	
257	fn fmt_tokens(n: u64) -> String {
258	    if n >= 1_000_000 {
259	        format!("{:.1}M", n as f64 / 1_000_000.0)
260	    } else if n >= 1_000 {
261	        format!("{:.1}K", n as f64 / 1_000.0)
262	    } else {
263	        format!("{}", n)
264	    }
265	}
266	
267	fn truncate(s: &str, max: usize) -> String {
268	    if s.len() <= max {
269	        s.to_string()
270	    } else {
271	        let end = s
272	            .char_indices()
273	            .take_while(|(i, _)| *i < max.saturating_sub(2))
274	            .last()
275	            .map(|(i, c)| i + c.len_utf8())
276	            .unwrap_or(0);
277	        format!("{}..", &s[..end])
278	    }
279	}
