1	use anyhow::{Context, Result};
2	use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
3	use rand::rngs::OsRng;
4	use std::fs;
5	use std::path::PathBuf;
6	
7	pub struct KeyPair {
8	    signing_key: SigningKey,
9	}
10	
11	impl KeyPair {
12	    pub fn generate() -> Self {
13	        let mut csprng = OsRng;
14	        Self {
15	            signing_key: SigningKey::generate(&mut csprng),
16	        }
17	    }
18	
19	    pub fn sign(&self, data: &[u8]) -> String {
20	        let sig = self.signing_key.sign(data);
21	        hex::encode(sig.to_bytes())
22	    }
23	
24	    pub fn public_key_hex(&self) -> String {
25	        hex::encode(self.signing_key.verifying_key().to_bytes())
26	    }
27	
28	    pub fn to_bytes(&self) -> [u8; 32] {
29	        self.signing_key.to_bytes()
30	    }
31	
32	    pub fn from_bytes(bytes: &[u8; 32]) -> Self {
33	        Self {
34	            signing_key: SigningKey::from_bytes(bytes),
35	        }
36	    }
37	}
38	
39	pub fn verify(pubkey_hex: &str, data: &[u8], sig_hex: &str) -> Result<bool> {
40	    let pubkey_bytes: [u8; 32] = hex::decode(pubkey_hex)
41	        .context("invalid pubkey hex")?
42	        .try_into()
43	        .map_err(|_| anyhow::anyhow!("pubkey must be 32 bytes"))?;
44	
45	    let sig_bytes: [u8; 64] = hex::decode(sig_hex)
46	        .context("invalid signature hex")?
47	        .try_into()
48	        .map_err(|_| anyhow::anyhow!("signature must be 64 bytes"))?;
49	
50	    let verifying_key = VerifyingKey::from_bytes(&pubkey_bytes)
51	        .context("invalid Ed25519 public key")?;
52	    let signature = ed25519_dalek::Signature::from_bytes(&sig_bytes);
53	
54	    Ok(verifying_key.verify(data, &signature).is_ok())
55	}
56	
57	fn keys_dir() -> Result<PathBuf> {
58	    let data_dir = dirs::data_dir()
59	        .context("could not determine platform data directory")?;
60	    let keys_path = data_dir.join("rtk").join("keys");
61	    Ok(keys_path)
62	}
63	
64	pub fn load_or_generate() -> Result<KeyPair> {
65	    let dir = keys_dir()?;
66	    fs::create_dir_all(&dir)
67	        .with_context(|| format!("failed to create keys dir: {}", dir.display()))?;
68	
69	    let key_file = dir.join("ed25519.key");
70	
71	    match fs::read(&key_file) {
72	        Ok(bytes) => {
73	            let key_bytes: [u8; 32] = bytes
74	                .try_into()
75	                .map_err(|_| anyhow::anyhow!("key file corrupted: expected 32 bytes"))?;
76	            return Ok(KeyPair::from_bytes(&key_bytes));
77	        }
78	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
79	        Err(e) => return Err(e).context("failed to read key file"),
80	    }
81	
82	    let kp = KeyPair::generate();
83	
84	    match fs::OpenOptions::new()
85	        .write(true)
86	        .create_new(true)
87	        .open(&key_file)
88	    {
89	        Ok(mut f) => {
90	            use std::io::Write;
91	            f.write_all(&kp.to_bytes())
92	                .with_context(|| format!("failed to write key: {}", key_file.display()))?;
93	        }
94	        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
95	            return load_or_generate();
96	        }
97	        Err(e) => return Err(e).context("failed to create key file"),
98	    }
99	
100	    #[cfg(unix)]
101	    {
102	        use std::os::unix::fs::PermissionsExt;
103	        let _ = fs::set_permissions(&key_file, fs::Permissions::from_mode(0o600));
104	    }
105	
106	    Ok(kp)
107	}
