110	mod tests {
111	    use super::*;
112	
113	    #[test]
114	    fn sign_verify_roundtrip() {
115	        let kp = KeyPair::generate();
116	        let data = b"test message";
117	        let sig = kp.sign(data);
118	        let pubkey = kp.public_key_hex();
119	        assert!(verify(&pubkey, data, &sig).unwrap());
120	    }
121	
122	    #[test]
123	    fn verify_wrong_data_fails() {
124	        let kp = KeyPair::generate();
125	        let sig = kp.sign(b"original");
126	        let pubkey = kp.public_key_hex();
127	        assert!(!verify(&pubkey, b"tampered", &sig).unwrap());
128	    }
129	
130	    #[test]
131	    fn keypair_serialization_roundtrip() {
132	        let kp = KeyPair::generate();
133	        let bytes = kp.to_bytes();
134	        let restored = KeyPair::from_bytes(&bytes);
135	        let data = b"consistency check";
136	        let sig = kp.sign(data);
137	        let pubkey = restored.public_key_hex();
138	        assert!(verify(&pubkey, data, &sig).unwrap());
139	    }
140	
141	    #[test]
142	    fn verify_invalid_hex_errors() {
143	        assert!(verify("not_hex", b"data", "also_not_hex").is_err());
144	    }
145	
146	    #[test]
147	    fn verify_wrong_length_errors() {
148	        assert!(verify("aabb", b"data", "ccdd").is_err());
149	    }
150	}
