1	//! `rtk budget` — budget governance status for the current project.
2	//!
3	//! Shows accumulated spend vs limits for all configured policy scopes.
4	//!
5	//! Usage:
6	//!   rtk budget           — human-readable table
7	//!   rtk budget --json    — machine-readable JSON
8	
9	use anyhow::{Context, Result};
10	use colored::Colorize;
11	use serde::Serialize;
12	
13	use crate::core::budget_policy::{
14	    BudgetPeriod, LimitAction, PolicyConfig, PolicyEngine, PolicyScope, Verdict, period_start,
15	};
16	use crate::core::cost_store::CostStore;
17	
18	/// One row in the budget status table.
19	#[derive(Debug, Serialize)]
20	pub struct BudgetRow {
21	    pub scope: String,
22	    pub id: String,
23	    pub spent_usd: f64,
24	    pub limit_usd: f64,
25	    pub pct: f64,
26	    pub status: String,
27	}
28	
29	pub fn run_budget(json: bool) -> Result<()> {
