    pub fn cleanup_old_records(&self) -> Result<usize> {
        let cutoff = chrono::Utc::now() - chrono::Duration::days(RETENTION_DAYS);
        let deleted = self.conn.execute(
            "DELETE FROM provenance_records WHERE timestamp < ?1",
            params![cutoff.to_rfc3339()],
        )?;
        Ok(deleted)
    }

    /// Query records with optional lower-bound timestamp, project path, and developer filters.
    ///
    /// `since_rfc3339` — inclusive lower bound (e.g. "2025-01-01T00:00:00+00:00"); `None` = all.
    /// `project_filter` — substring match on `file_path`; `None` = no filter.
    /// `dev_filter`     — exact match on `developer_id`; `None` = no filter.
    pub fn query_range(
        &self,
        since_rfc3339: Option<&str>,
        project_filter: Option<&str>,
        dev_filter: Option<&str>,
    ) -> Result<Vec<ProvenanceRecord>> {
        // Build WHERE clauses dynamically to avoid parameter count mismatches.
        let mut clauses: Vec<String> = Vec::new();
        if since_rfc3339.is_some() {
            clauses.push("timestamp >= ?1".to_string());
        }
        if project_filter.is_some() {
            let idx = clauses.len() + 1;
            clauses.push(format!("file_path LIKE ?{}", idx));
        }
        if dev_filter.is_some() {
            let idx = clauses.len() + 1;
            clauses.push(format!("developer_id = ?{}", idx));
        }

        let where_clause = if clauses.is_empty() {
            String::new()
        } else {
            format!("WHERE {}", clauses.join(" AND "))
        };

        let sql = format!(
            "SELECT id, model_id, model_version, prompt_hash, code_hash, file_path,
                    start_line, end_line, contributor_type, attestation_sig,
                    timestamp, developer_id, session_id
             FROM provenance_records {} ORDER BY timestamp ASC",
            where_clause
        );

        // Collect bound values in order.
        let mut bound_strings: Vec<String> = Vec::new();
        if let Some(since) = since_rfc3339 {
            bound_strings.push(since.to_string());
        }
        if let Some(proj) = project_filter {
            bound_strings.push(format!("%{}%", proj));
        }
        if let Some(dev) = dev_filter {
            bound_strings.push(dev.to_string());
        }

        let mut stmt = self.conn.prepare(&sql)?;
        let records = stmt
            .query_map(
                rusqlite::params_from_iter(bound_strings.iter()),
                |row| {
                    Ok(ProvenanceRecord {
                        id: Some(row.get(0)?),
                        model_id: row.get(1)?,
                        model_version: row.get(2)?,
                        prompt_hash: row.get(3)?,
                        code_hash: row.get(4)?,
                        file_path: row.get(5)?,
                        start_line: row.get(6)?,
                        end_line: row.get(7)?,
                        contributor_type: ContributorType::from_str(&row.get::<_, String>(8)?),
                        attestation_sig: row.get(9)?,
                        timestamp: row.get(10)?,
                        developer_id: row.get(11)?,
                        session_id: row.get(12)?,
                    })
                },
            )?
            .collect::<std::result::Result<Vec<_>, _>>()?;

        Ok(records)
    }
}

